var o=[{title:`Esforço e dano`,text:`A fadiga muscular, a respiração pesada e uma ardência temporária podem acompanhar o exercício intenso. A dor aguda, o desconforto articular novo, a dor que se espalha ou as tonturas não são conquistas. O corpo adapta-se quando um treino difícil mas tolerável é seguido de recuperação suficiente. A dor não é o que o faz funcionar.`},{title:`As dores musculares são uma má pontuação`,text:`As dores musculares de início tardio são especialmente comuns depois de exercício pouco habitual ou intenso. Costumam desaparecer à medida que o corpo se habitua a um movimento, enquanto a sua força e a sua condição física continuam a melhorar. Uma sessão que o deixa quase sem dores pode ainda assim ser produtiva, e demasiadas dores podem dificultar treinar com regularidade.`},{title:`Progresso sem castigo`,text:`Escolha repetições que sejam desafiantes mas controladas, aumente gradualmente as exigências do treino e inclua dias de descanso ou mais fáceis. Terminar uma série com algumas repetições de reserva pode ser sensato. A investigação não mostra que o adulto saudável médio precise de chegar vezes sem conta à falha muscular momentânea para obter resultados que valham a pena.`},{title:`Exemplo`,text:`Um iniciante que faz dois treinos de corpo inteiro por semana e acrescenta de forma constante repetições de agachamento e de flexão pode progredir sem se sentir destruído depois de cada sessão.`},{title:`Usar o TrainUp`,text:`Depois de um treino, avalia o esforço da sessão (RPE) e indica qualquer dor com a zona do corpo e o exercício. Se algo doer durante um treino, use «Sinto dor» para terminar o exercício de imediato; fica fora dos seus planos até o retomar no Perfil. Qualquer dor recente significa que o seu próximo plano não fica mais difícil. A dor nova ou intensa é uma razão para parar e a fazer avaliar.`}];var s=[{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Orientações práticas do ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`},{label:`NHS: dor nas articulações`,url:`https://www.nhs.uk/symptoms/joint-pain/`}];var r={sections:o,sources:s};export{r as default,o as sections,s as sources};